            otherData: {
                notification_url: "https://nyox.tech/api/notifications"
            }
        };

        try {
            // *** IMPORTANTE: MOCKADO. Substituir pela chamada real ***
            const paymentResponse = await this.paymentProcessor.getPayment(92690421680); 
            // const paymentResponse = await this.paymentProcessor.processPayment(paymentOptions);

            await interaction.deferUpdate();

            if (!paymentResponse || !paymentResponse.id) {
                throw new Error("Falha na criação do pagamento pelo processador.");
            }

            // Salva registro de pagamento e atualiza carrinho
            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: paymentOptions.amount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
