     * @param {import('discord.js').Interaction} interaction - Interação do botão.
     * @param {"add" | "remove"} action - Ação a ser executada.
     */
    updateCartQuantity = async (interaction, action) => {
        try {
            if (action === "add") {
                this.quantity += 1;
            } else if (action === "remove") {
                this.quantity -= 1;

                if (this.quantity < 1) {
                    this.quantity = 1; // Garante um mínimo de 1
                    await interaction.reply({
                        embeds: [new EmbedBuilder().setDescription("❌ | Você não pode diminuir mais, quantidade mínima é 1.")],
                        ephemeral: true
                    });
                    return;
                }
            }

            // Atualiza DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            // Atualiza mensagem e reinicia timer
            await interaction.update(this.cratePlanItens());
            this.setInactivityTimer(() => this.handleInactivity(), INACTIVITY_DELAY_MS);

        } catch (error) {
            console.error("Erro ao atualizar quantidade do carrinho:", error);
