    /**
     * Lida com o cancelamento da ordem (pelo botão do carrinho).
     * @param {import('discord.js').Interaction} interaction - Interação do botão.
     */
    handleCancellation = async (interaction) => {
        try {
            const logEmbed = this.createLogEmbed("Carrinho Cancelado", "Cancelado pelo usuário.");
            await this.sendLog(logEmbed);

            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete().catch(e => console.error("Erro ao deletar thread no cancelamento:", e));
            }

            // Responde ao usuário na thread
            await interaction.reply({ 
