        } catch (error) {
            console.error("Erro ao cancelar pagamento:", error);
            await interaction.reply({ content: "Não foi possível cancelar o pagamento no sistema. Por favor, verifique com o suporte.", ephemeral: true });
        }
    };

    /**
     * Cria o carrinho e inicia o processo.
     */
    createCart = async () => {
        try {
            // 1. Verifica carrinho existente
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel && guildChannel.type === ChannelType.PrivateThread) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity;
                    this.selectedPlan = existingCart.selectedPlan;
                    this.days = this.getDaysFromPlan(this.selectedPlan);

                    return this.interaction 
                        ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) 
                        : true;
                }
            }

            await this.interaction.reply({ content: "Aguarde um momento, estou criando seu carrinho...", ephemeral: true });

            // 2. Cria Thread Privada
            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras",
                members: [this.user.id],
                permissionOverwrites: [
                    {
                        id: this.user.id,
                        allow: [PermissionsBitField.Flags.ViewChannel],
                        deny: [] // Permite ver e interagir
                    },
                    {
                        id: this.interaction.guild.id,
                        deny: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages]
                    }
                ]
            });

            this.channel = thread;

            // 3. Salva no DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando...",
                    selectedPlan: this.selectedPlan || "mensal" // Default para evitar erro
                },
                { upsert: true, new: true }
            );

            // 4. Timer e Resposta Inicial
            this.setInactivityTimer(() => this.handleInactivity(), INACTIVITY_DELAY_MS);
            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            // 5. Envia mensagem de seleção de plano
            const initialEmbedData = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbedData);

            // Chama a seleção inicial (pode ser 30 dias por padrão, ou deixar para o usuário escolher)
            await this.handlePlanSelection(this.interaction, "mensal"); 

        } catch (error) {
            console.error("Erro crítico ao criar carrinho:", error);
            if (this.interaction) {
                 await this.interaction.reply({ content: "❌ Erro interno ao iniciar o carrinho. Tente novamente mais tarde.", ephemeral: true });
            }
        }
    };

    /**
     * Helper para obter dias do plano.
     * @param {string} plan - Nome do plano.
     * @returns {number}
     */
    getDaysFromPlan = (plan) => {
        switch (plan) {
            case "mensal": return 30;
            case "quizena": return 15;
            case "semanal": return 7;
            default: return 0;
        }
    }

    /**
     * Cria a embed de log genérica.
     * @param {string} title - Título do log.
     * @param {string} motive - Motivo do log.
     * @returns {EmbedBuilder}
     */
    createLogEmbed(title, motive) {
        return new EmbedBuilder()
            .setTitle(`📝 ${title}`)
            .setColor("#FF4500")
            .setAuthor({ 
                name: this.client.user.username, 
                iconURL: this.client.user.displayAvatarURL({ dynamic: true }) 
            })
            .setFooter({ 
                text: this.interaction.guild.name, 
                iconURL: this.interaction.guild.iconURL({ dynamic: true }) 
            })
            .addFields(
                { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                { name: '🛒 | Carrinho ID:', value: `**${this.cartId}**`, inline: false },
                { name: '📝 | Produto:', value: `**${this.productData.productName}**`, inline: false },
                { name: '🕒 | Data / Horário:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false },
                { name: '❔ | Motivo:', value: motive, inline: false }
            );
    }


    /**
     * Executa o método de criar carrinho.
     */
    run = async (start) => {
        await this.createCart();

        // Collector com tempo de expiração maior (ex: 10 minutos = 600000ms)
        const collector = this.channel.createMessageComponentCollector({ 
            componentType: ComponentType.Button, 
            time: 600000 
        });

        collector.on("collect", async (btnInteraction) => {
            // Garante que a interação veio do usuário do carrinho
            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);

            // Reinicia o timer em qualquer interação válida
            this.setInactivityTimer(() => this.handleInactivity(), INACTIVITY_DELAY_MS);

            try {
                switch (btnInteraction.customId) {
                    case "7DiasCart":
                    case "15DiasCart":
                    case "30DiasCart":
                        await btnInteraction.deferUpdate();
                        await this.handlePlanSelection(btnInteraction);
                        break;

                    case "cancelOrder":
                        await this.handleCancellation(btnInteraction);
                        break;

                    case "addToCart":
                        await this.updateCartQuantity(btnInteraction, "add");
                        break;

                    case "removeFromCart":
                        await this.updateCartQuantity(btnInteraction, "remove");
                        break;

                    case "finalizePurchase":
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case "pixCopyPaste":
                    case "qrCode":
                        // Obtém detalhes de pagamento após a criação
                        const payment = await Cart.findOne({ channelId: this.channel.id });
                        if (payment && payment.paymentId) {
                            const paymentDetails = await this.paymentProcessor.getPayment(payment.paymentId);

                            if (btnInteraction.customId === "qrCode" && paymentDetails.attachment) {
                                await btnInteraction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                            } else if (btnInteraction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                                await btnInteraction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                            } else {
                                await btnInteraction.reply({ content: "Detalhes do pagamento não disponíveis.", ephemeral: true });
                            }
                        } else {
                            await btnInteraction.reply({ content: "Pagamento não encontrado ou ainda não gerado.", ephemeral: true });
                        }
                        break;

                    case "cancelPayment":
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    default:
                        console.log(`Custom ID desconhecido: ${btnInteraction.customId}`);
                }
            } catch (error) {
                console.error(`Erro ao processar interação ${btnInteraction.customId}:`, error);
                await btnInteraction.reply({ content: "❌ Ocorreu um erro ao executar esta ação. Por favor, tente novamente ou entre em contato com o suporte.", ephemeral: true });
            }
        });

        collector.on("end", () => {
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
            console.log(`[Cart ${this.cartId}] Collector encerrado. Timer limpo.`);
        });
    };

    /**
     * Helper para capitalizar strings.
     * @param {string} str 
     * @returns {string}
     */
    capitalize = (str) => {
        if (typeof str !== 'string' || str.length === 0) return '';
        return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    };
}

module.exports = CartClass;
